LOGIN = '<!-- core-login:start -->\n<main id="login-screen" data-core-login data-core-login-product="KagNode. VPN"><section class="kn-core-login-card"><header class="kn-core-login-heading"><svg class="kn-core-login-mark" viewBox="0 0 64 64" aria-hidden="true" focusable="false"><g transform="scale(2)" fill="#2563eb"><path d="M4 18C4 9 11 4 23 5L18 27C10 28 4 25 4 18Z"/><path d="m25 11 4 5-3 10-4-3Z"/></g></svg><p class="kn-core-login-product">KagNode. VPN</p><h1>Sign in</h1><p>Use your account to continue to KagNode VPN.</p></header><div class="kn-core-login-content"><form method="post" action="/manage/login" data-core-login-progressive>\n  <div class="kn-core-login-field">\n    <label for="login-username">Username</label\n    ><input\n      id="login-username"\n      name="username"\n      autocomplete="username"\n      required\n    />\n  </div>\n  <div data-core-login-credentials>\n  <div class="kn-core-login-field">\n    <label for="login-password">Password</label\n    ><input\n      id="login-password"\n      type="password"\n      name="password"\n      minlength="12"\n      maxlength="256"\n      autocomplete="current-password"\n      required\n    />\n  </div>\n  <div class="kn-core-login-field">\n    <label for="login-code">Authenticator or recovery code</label\n    ><input\n      id="login-code"\n      name="code"\n      autocomplete="one-time-code"\n      required\n      maxlength="128"\n    />\n  </div>\n  </div>\n  <button type="submit" data-core-login-submit>Sign in</button>\n</form>\n<p>\n  Only approved local administrators can sign in. Sessions end after 30 minutes\n  of inactivity or eight hours.\n</p>\n<details>\n  <summary>Enroll a new administrator</summary>\n  <form method="post" action="/manage/enroll">\n    <div class="kn-core-login-field">\n      <label for="login-token">Private enrollment token</label\n      ><input id="login-token" name="token" required autocomplete="off" />\n    </div>\n    <button type="submit">Start enrollment</button>\n  </form>\n</details>\n</div><div class="kn-core-login-provider" id="provider-login" hidden><button type="button" data-core-login-provider disabled>\n  Login with KagNode\n</button>\n<div data-core-login-status role="status"></div>\n<form id="provider-mfa" hidden>\n  <p>\n    KagNode identity confirmed. Enter your local authenticator or recovery code.\n  </p>\n  <div class="kn-core-login-field">\n    <label for="login-code">Authenticator or recovery code</label\n    ><input\n      id="login-code"\n      name="code"\n      autocomplete="one-time-code"\n      required\n      maxlength="128"\n    />\n  </div>\n  <button type="submit" data-core-login-submit>Continue</button>\n  <p id="provider-error" role="alert"></p>\n  <a href="/manage">Use local sign-in</a>\n</form>\n</div></section></main>\n<!-- core-login:end -->\n'
